import {sizeEnergy} from './energy.mjs';
const form=document.getElementById('energy-form'),list=document.getElementById('energy-loads'),output=document.getElementById('energy-results'),error=document.getElementById('energy-error');
const fmt=value=>new Intl.NumberFormat('pt-BR',{maximumFractionDigits:1}).format(value);
let nextId=0;
function addLoad(load={name:'Outro aparelho',mode:'watts',count:1,amount:10,usage:1,ac:true,chargeWatts:20}){
 const row=document.createElement('fieldset');row.className='energy-load';row.dataset.id=String(nextId++);
 row.innerHTML='<legend>Aparelho</legend><label class="energy-load-name">Nome<input data-field="name" maxlength="60"></label><label>Quantidade<input data-field="count" type="number" min="0" max="100" step="1" required></label><label>Forma de cálculo<select data-field="mode"><option value="watts">Potência × horas</option><option value="charge">Energia por carga</option></select></label><label><span data-amount-label>Potência (W)</span><input data-field="amount" type="number" min="0" max="100000" step="0.1" required></label><label><span data-usage-label>Horas por dia</span><input data-field="usage" type="number" min="0" max="24" step="0.1" required></label><label data-port-label>Potência da porta por aparelho (W)<input data-field="chargeWatts" type="number" min="0" max="1000" step="1" required></label><label class="energy-ac"><input data-field="ac" type="checkbox">Precisa de tomada AC</label><button type="button" class="energy-remove" aria-label="Remover aparelho">Remover</button>';
 for(const[key,value]of Object.entries(load)){const field=row.querySelector(`[data-field="${key}"]`);if(field){if(key==='ac')field.checked=value;else field.value=value;}}
 row.querySelector('.energy-remove').addEventListener('click',()=>{row.remove();recalculate();});list.append(row);setLabels(row);recalculate();
}
function setLabels(row){const charge=row.querySelector('[data-field="mode"]').value==='charge';row.querySelector('[data-amount-label]').textContent=charge?'Energia por carga (Wh)':'Potência (W)';row.querySelector('[data-usage-label]').textContent=charge?'Cargas por dia':'Horas por dia';row.querySelector('[data-port-label]').hidden=!charge;}
function recalculate(){
 if(!form||!form.checkValidity()){error.textContent='Confira os campos para atualizar o dimensionamento.';output.replaceChildren();return;}
 const read=name=>Number(form.elements.namedItem(name).value);
 const loads=[...list.querySelectorAll('.energy-load')].map(row=>{const result={};row.querySelectorAll('[data-field]').forEach(field=>result[field.dataset.field]=field.type==='checkbox'?field.checked:['name','mode'].includes(field.dataset.field)?field.value:Number(field.value));return result;});
 try{const input={loads,days:read('days'),reserve:read('reserve')/100,efficiency:read('efficiency')/100,usable:read('usable')/100,sunHours:read('sunHours'),solarYield:read('solarYield')/100,recoveryDays:read('recoveryDays'),voltage:read('voltage'),startupWatts:read('startupWatts'),idleWatts:read('idleWatts'),idleHours:read('idleHours')};const r=sizeEnergy(input);error.textContent='';
 if(r.dailyWh===0){output.innerHTML='<p>Adicione o consumo de pelo menos um aparelho para dimensionar a reserva.</p>';return;}
 const solar=r.solarRecoveryW===null?'Sem geração solar':fmt(Math.ceil(r.solarRecoveryW))+' W';
 output.innerHTML=`<div class="energy-totals"><article><span>Consumo diário</span><strong>${fmt(r.dailyWh)} Wh</strong></article><article><span>Bateria nominal mínima</span><strong>${fmt(Math.ceil(r.batteryWh))} Wh</strong><small>${fmt(r.batteryAh)} Ah em ${fmt(input.voltage)} V</small></article><article><span>Painéis para consumo + reposição</span><strong>${solar}</strong><small>Reserva reposta em ${fmt(input.recoveryDays)} dias de sol</small></article></div><div class="energy-recommendations"><h3>O que procurar para esse cenário</h3><div class="energy-hardware"></div></div>`;
 const hardware=output.querySelector('.energy-hardware');const card=(title,text)=>{const a=document.createElement('article'),h=document.createElement('h4'),p=document.createElement('p');h.textContent=title;p.textContent=text;a.append(h,p);hardware.append(a);};
 if(r.acWatts===0&&r.batteryWh<=200)card('Power bank USB-C / bateria portátil DC',`Procure capacidade nominal de pelo menos ${fmt(Math.ceil(r.batteryWh))} Wh e saídas compatíveis com ${fmt(r.dcWatts)} W simultâneos. Confira a potência por porta e os protocolos USB-C dos seus aparelhos. Para comparar mAh, use a tensão interna indicada no produto.`);
 else card(r.acWatts?'Estação de energia portátil com tomada':'Estação portátil com saídas DC',`Capacidade nominal de pelo menos ${fmt(Math.ceil(r.batteryWh))} Wh, considerando a fração utilizável de ${fmt(input.usable*100)}%. ${r.acWatts?`Saída AC contínua de ao menos ${fmt(Math.ceil(r.inverterContinuousW))} W e pico de ao menos ${fmt(Math.ceil(r.inverterSurgeW))} W.`:`Saídas DC compatíveis com ${fmt(r.dcWatts)} W simultâneos.`} Confira tensão, portas e limites do fabricante.`);
 card('Painel solar portátil ou fixo',r.solarRecoveryW===null?'Com zero horas de sol pleno, a recarga solar não pode ser dimensionada para esse período. A autonomia depende da bateria já carregada.':`Ao menos ${fmt(Math.ceil(r.solarRecoveryW))} W nominais para o consumo e a reposição em ${fmt(input.recoveryDays)} dias de sol. Só para repor o consumo diário: ${fmt(Math.ceil(r.solarDailyW))} W. Use entrada solar/MPPT compatível com tensão em circuito aberto, corrente, potência e conectores do painel.`);
 card('Banco de baterias estacionárias',`No cenário informado: pelo menos ${fmt(Math.ceil(r.batteryWh))} Wh nominais (${fmt(r.batteryAh)} Ah em ${fmt(input.voltage)} V). Ajuste a fração utilizável à química e ao manual da bateria; chumbo-ácido e LiFePO4 não devem receber a mesma premissa automaticamente. O conjunto precisa de controlador, proteção e conversor/inversor compatíveis.`);
 if(r.acWatts&&input.startupWatts===0)card('Aparelhos com motor ou compressor','Você não informou pico de partida. Confira esse dado antes de escolher o inversor; a potência contínua sozinha não confirma que um motor vai iniciar.');
 }catch{output.replaceChildren();error.textContent='Revise as unidades e os limites dos campos.';}
}
form?.addEventListener('submit',e=>e.preventDefault());form?.addEventListener('input',recalculate);form?.addEventListener('change',event=>{const row=event.target.closest('.energy-load');if(row)setLabels(row);recalculate();});document.getElementById('energy-add')?.addEventListener('click',()=>{if(list.children.length<30)addLoad();});
if(form){addLoad({name:'Celular',mode:'charge',count:2,amount:15,usage:1,ac:false,chargeWatts:20});addLoad({name:'Lâmpada USB',mode:'watts',count:2,amount:9,usage:4,ac:false,chargeWatts:0});}
